import ghidra.app.script.GhidraScript;
import ghidra.program.model.address.*;
import ghidra.program.model.symbol.SourceType;
public class N3DPass8Repair extends GhidraScript {
 public void run() throws Exception {
  var fm=currentProgram.getFunctionManager();
  var old=getInstructionAt(toAddr("1008:3c7f"));
  if(old==null || old.getLength()!=4)throw new Exception("Unexpected pre-repair boundary");
  fm.getFunctionAt(toAddr("1008:3c3d")).setBody(new AddressSet(toAddr("1008:3c3d"),toAddr("1008:3c7e")));
  clearListing(toAddr("1008:3c7f"),toAddr("1008:3cb6"));
  if(!disassemble(toAddr("1008:3c80")))throw new Exception("Decode failed");
  var lookup=createFunction(toAddr("1008:3c80"),"RE_crt_lookup_runtime_error_string");
  if(lookup==null)throw new Exception("Create lookup failed");
  lookup.setComment("Confirmed pass 8: near DS:2242 packed WORD id / NUL string records; FFFF sentinel. Returns near pointer following matching id, else AX=0. Called at 3C48 and 3CCD. DF=0 and terminated table assumed.");
  if(!disassemble(toAddr("1000:076a")))throw new Exception("Callback decode failed");
  var cb=createFunction(toAddr("1000:076a"),"RE_allocation_failure_throw_callback");
  if(cb==null)throw new Exception("Create callback failed");
  cb.setComment("Confirmed pass 8: callback pointer passed at 0777/077A to 601A -> 5FF0, stored DS:094A/094C, indirectly called by allocator 5AB0. Calls 4564 then XOR AX,AX; RETF. Exception role inferred from downstream THROW path; full exceptional ABI unknown.");
  var fatal=fm.getFunctionAt(toAddr("1008:3c3d"));
  fatal.setName("RE_crt_fatal_runtime_error",SourceType.USER_DEFINED);
  fatal.setNoReturn(true);
  fatal.setComment("Pass 8: bounded body through CALL FATALEXIT at 3C7A, ends 3C7E. Old fallthrough consumed padding 3C7F and misdecoded separate lookup entry 3C80. Does not establish external Win16 API ABI correctness.");
  fm.getFunctionAt(toAddr("1008:3d59")).setName("RE_crt_translate_error_AX",SourceType.USER_DEFINED);
  println("PASS8_REPAIR_COMPLETE two new entries; one offcut target repaired; no binary bytes patched");
 }
}

