import csv,json
from pathlib import Path
R=Path(__file__).resolve().parents[1]
def audit(folder):
 ins=list(csv.DictReader((R/folder/'listing.tsv').open(),delimiter='\t'))
 starts={x['address'] for x in ins};interior={}
 for x in ins:
  s,a=x['address'].split(':');a=int(a,16)
  for i in range(1,len(x['bytes'])//2):interior[f'{s}:{a+i:04x}']=x
 out=[]
 for ref in csv.DictReader((R/folder/'references.tsv').open(),delimiter='\t'):
  if ref['type']=='UNCONDITIONAL_CALL' and ref['to'] in interior:
   i=interior[ref['to']];out.append(dict(call=ref['from'],target=ref['to'],instruction=i['address'],bytes=i['bytes'],disassembly=i['instruction']))
 return out
out={'before':audit('pass7-results'),'after':audit('pass8-results'),'scope':'Explicit UNCONDITIONAL_CALL references landing inside an existing instruction. Not a complete function-boundary audit.'}
(R/'pass8/offcut_call_audit.json').write_text(json.dumps(out,indent=2)+'\n');print(json.dumps(out,indent=2))

